}

type Tab = 'dashboard' | 'products' | 'categories' | 'partners' | 'banners' | 'projects' | 'settings' | 'about';

const AdminPanel: React.FC<AdminPanelProps> = (props) => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
