                  <p className="text-stone-400 font-bold uppercase text-[10px]">Categorias</p>
               </div>
               <div className="bg-white p-8 rounded-3xl shadow-sm border border-stone-200">
                  <Briefcase size={24} className="text-purple-600 mb-4" />
