      </main>

      {/* MODAL PRODUTO */}
      {editingProduct && (
        <div className="fixed inset-0 bg-stone-900/95 z-[200] flex items-center justify-center p-6 overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl p-10 max-h-[90vh] overflow-y-auto">
